/* LearnCamp — the hub (index.html) and the class page (class.html?c=1).
 * Class data lives in data/class-NN.js (generated by tools/build.py) and calls
 * LC.register({...}); data/catalog.js lists the classes for the hub. */
(function () {
    'use strict';

    const LC = window.LC = { classes: {}, catalog: [] };
    LC.register = c => { LC.classes[c.id] = c; };
    LC.setCatalog = list => { LC.catalog = list; };

    const $ = (sel, el = document) => el.querySelector(sel);
    const $$ = (sel, el = document) => [...el.querySelectorAll(sel)];
    const esc = s => String(s).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
    const pad2 = n => String(n).padStart(2, '0');
    const LEVELS = { 1: '⭐ Warm-up', 2: '⭐⭐ Core', 3: '⭐⭐⭐ Challenge' };

    // ── Saved progress (per browser) ─────────────────────────────────────
    const store = {
        get(k, d) { try { const v = localStorage.getItem('lc:' + k); return v === null ? d : JSON.parse(v); } catch (e) { return d; } },
        set(k, v) { try { localStorage.setItem('lc:' + k, JSON.stringify(v)); } catch (e) { /* private mode */ } },
    };
    const solvedSet = cid => new Set(store.get(`solved:${cid}`, []));
    function markSolved(cid, slug) { const s = solvedSet(cid); s.add(slug); store.set(`solved:${cid}`, [...s]); }

    /** The same comparison the build uses: trailing spaces and trailing blank lines don't matter. */
    const norm = s => String(s).replace(/\r\n/g, '\n').replace(/[ \t]+$/gm, '').replace(/\n+$/, '');

    // ── Judge: a Pyodide worker with a time limit ────────────────────────
    const Judge = {
        worker: null, ready: null, seq: 0, pending: null,
        start() {
            this.worker = new Worker('judge-worker.js');
            this.ready = new Promise((resolve, reject) => {
                this.worker.onmessage = e => {
                    const m = e.data;
                    if (m.type === 'ready') return resolve();
                    if (m.type === 'fail') return reject(new Error(m.err));
                    if (this.pending && m.id === this.pending.id) { const p = this.pending; this.pending = null; clearTimeout(p.timer); p.resolve(m); }
                };
                this.worker.onerror = () => reject(new Error('Python could not start.'));
            });
            return this.ready;
        },
        /** Run code with stdin. Resolves {out, err, ms, tle}. Never rejects for user errors. */
        async run(code, input, limitMs = 4000) {
            if (!this.worker) this.start();
            await this.ready;
            return new Promise(resolve => {
                const id = ++this.seq;
                const timer = setTimeout(() => {   // too slow: kill Python and start a fresh one
                    this.pending = null;
                    this.worker.terminate(); this.worker = null;
                    resolve({ out: '', err: '', ms: limitMs, tle: true });
                }, limitMs);
                this.pending = { id, resolve, timer };
                this.worker.postMessage({ id, code, input });
            });
        },
    };

    // ── A tiny code editor on a textarea ─────────────────────────────────
    function editor(ta, onChange) {
        ta.spellcheck = false;
        ta.addEventListener('keydown', e => {
            const s = ta.selectionStart, en = ta.selectionEnd, v = ta.value;
            if (e.key === 'Tab') {
                e.preventDefault();
                if (e.shiftKey) {                              // dedent the current line
                    const ls = v.lastIndexOf('\n', s - 1) + 1;
                    const n = (v.slice(ls).match(/^ {1,4}/) || [''])[0].length;
                    if (n) { ta.value = v.slice(0, ls) + v.slice(ls + n); ta.selectionStart = ta.selectionEnd = Math.max(ls, s - n); }
                } else {
                    ta.value = v.slice(0, s) + '    ' + v.slice(en);
                    ta.selectionStart = ta.selectionEnd = s + 4;
                }
                onChange && onChange();
            } else if (e.key === 'Enter') {                    // keep the indentation; indent after ':'
                e.preventDefault();
                const ls = v.lastIndexOf('\n', s - 1) + 1, line = v.slice(ls, s);
                let ind = (line.match(/^ */) || [''])[0];
                if (/:\s*$/.test(line)) ind += '    ';
                ta.value = v.slice(0, s) + '\n' + ind + v.slice(en);
                ta.selectionStart = ta.selectionEnd = s + 1 + ind.length;
                onChange && onChange();
            }
        });
        ta.addEventListener('input', () => onChange && onChange());
    }

    function loadScript(src) {
        return new Promise((resolve, reject) => {
            const s = document.createElement('script');
            s.src = src; s.onload = resolve; s.onerror = () => reject(new Error('Could not load ' + src));
            document.head.appendChild(s);
        });
    }

    // ═════════════════════════════════════════════════════════════════════
    // Hub
    // ═════════════════════════════════════════════════════════════════════
    async function hub() {
        await loadScript('data/catalog.js');
        $('#lc-classes').innerHTML = LC.catalog.map(c => {
            const solved = solvedSet(c.id).size;
            return `<a class="lc-class-card" href="class.html?c=${c.id}">
                <div class="lc-class-num">Class ${c.id}</div>
                <h3>${esc(c.title)}</h3>
                <p>${esc(c.blurb)}</p>
                <div class="lc-progress"><div style="width:${Math.round(100 * solved / c.problems)}%"></div></div>
                <div class="lc-progress-text">${solved} / ${c.problems} problems solved</div>
            </a>`;
        }).join('') + `<div class="lc-class-card lc-soon"><div class="lc-class-num">Coming next</div>
            <h3>Functions · A game project</h3><p>More classes are on the way.</p></div>`;
    }

    // ═════════════════════════════════════════════════════════════════════
    // Class page
    // ═════════════════════════════════════════════════════════════════════
    async function classPage() {
        const cid = Number(new URLSearchParams(location.search).get('c')) || 1;
        try { await loadScript(`data/class-${pad2(cid)}.js`); } catch (e) { $('#lc-title').textContent = 'This class is not available yet.'; return; }
        const C = LC.classes[cid];
        document.title = `Class ${cid}: ${C.title} - LearnCamp - KidsLearn`;
        $('#lc-title').textContent = `Class ${cid}: ${C.title}`;
        $('#lc-subtitle').textContent = C.blurb;

        // Tabs
        const show = name => {
            $$('.lc-tab').forEach(t => t.classList.toggle('active', t.dataset.tab === name));
            $('#lc-tutorial').hidden = name !== 'tutorial';
            $('#lc-problems').hidden = name !== 'problems';
        };
        $$('.lc-tab').forEach(t => t.addEventListener('click', () => {
            show(t.dataset.tab);
            if (t.dataset.tab === 'problems' && !location.hash.startsWith('#p=')) history.replaceState(null, '', '#problems');
            if (t.dataset.tab === 'tutorial') history.replaceState(null, '', '#tutorial');
        }));

        renderTutorial(C);
        const pane = renderProblemList(C);
        const fromHash = () => {
            const m = location.hash.match(/^#p=([a-z0-9-]+)/);
            if (m && C.problems.some(p => p.slug === m[1])) { show('problems'); pane.open(m[1]); }
            else if (location.hash === '#problems') { show('problems'); pane.open(store.get(`last:${cid}`, C.problems[0].slug)); }
            else { show('tutorial'); pane.open(store.get(`last:${cid}`, C.problems[0].slug)); }
        };
        window.addEventListener('hashchange', fromHash);
        fromHash();
        // Start Python in the background so the first Run is quick.
        Judge.start().catch(() => {});
    }

    // ── Tutorial ─────────────────────────────────────────────────────────
    function renderTutorial(C) {
        const el = $('#lc-tutorial');
        el.innerHTML = `<section class="lc-card lc-summary"><h2>🎯 In this class</h2>${C.summary}</section>` +
            C.tutorial.map((s, i) => `<section class="lc-card"><h2>${i + 1}. ${s.h}</h2>${s.html}</section>`).join('') +
            `<div class="lc-center"><button class="lc-btn" id="lc-go-problems">Now try the ${C.problems.length} problems →</button></div>`;
        $('#lc-go-problems').addEventListener('click', () => { location.hash = '#problems'; });
        // Every <pre class="try"> becomes a little playground. data-input gives it stdin.
        $$('pre.try', el).forEach(pre => {
            const code = pre.textContent.replace(/^\n/, '').replace(/\s+$/, '');
            const input = pre.dataset.input != null ? pre.dataset.input.replace(/\\n/g, '\n') : null;
            const box = document.createElement('div');
            box.className = 'lc-try';
            box.innerHTML = `<textarea class="lc-code" rows="${Math.min(18, code.split('\n').length + 1)}">${esc(code)}</textarea>
                ${input != null ? `<label class="lc-small">Input</label><textarea class="lc-stdin" rows="${Math.min(6, input.split('\n').length + 1)}">${esc(input)}</textarea>` : ''}
                <div class="lc-row"><button class="lc-btn small">▶ Run</button><button class="lc-btn ghost small">↺ Reset</button></div>
                <pre class="lc-out" hidden></pre>`;
            pre.replaceWith(box);
            const [ta, stdinTa] = [$('.lc-code', box), $('.lc-stdin', box)];
            editor(ta);
            const out = $('.lc-out', box);
            const [runBtn, resetBtn] = $$('button', box);
            runBtn.addEventListener('click', async () => {
                out.hidden = false; out.className = 'lc-out'; out.textContent = '🐍 Running…';
                runBtn.disabled = true;
                try {
                    const r = await Judge.run(ta.value, stdinTa ? stdinTa.value + (stdinTa.value.endsWith('\n') ? '' : '\n') : '');
                    out.textContent = r.tle ? '⏱ Stopped: it ran too long (an endless loop?).' : (r.out + (r.err ? (r.out ? '\n' : '') + r.err : '')) || '(no output)';
                    if (r.err || r.tle) out.classList.add('bad');
                } catch (e) { out.textContent = '⚠️ Python could not load. Check your internet connection.'; out.classList.add('bad'); }
                runBtn.disabled = false;
            });
            resetBtn.addEventListener('click', () => { ta.value = code; if (stdinTa) stdinTa.value = input; out.hidden = true; });
        });
    }

    // ── Problems ─────────────────────────────────────────────────────────
    function renderProblemList(C) {
        const cid = C.id;
        const list = $('#lc-list');
        const paintList = () => {
            const solved = solvedSet(cid);
            list.innerHTML = `<div class="lc-list-head">${solved.size} / ${C.problems.length} solved</div>` +
                C.problems.map((p, i) => `<a href="#p=${p.slug}" class="lc-item${solved.has(p.slug) ? ' done' : ''}" data-slug="${p.slug}">
                    <span class="lc-item-n">${i + 1}</span><span class="lc-item-t">${esc(p.title)}</span>
                    <span class="lc-item-l">${'⭐'.repeat(p.level)}</span>${solved.has(p.slug) ? '<span class="lc-tick">✓</span>' : ''}</a>`).join('');
        };
        paintList();
        let current = null;

        function open(slug) {
            const idx = C.problems.findIndex(p => p.slug === slug);
            const p = C.problems[idx < 0 ? 0 : idx];
            current = p;
            store.set(`last:${cid}`, p.slug);
            $$('.lc-item', list).forEach(a => a.classList.toggle('active', a.dataset.slug === p.slug));
            const key = `code:${cid}:${p.slug}`;
            const view = $('#lc-view');
            view.innerHTML = `
                <div class="lc-card">
                    <div class="lc-p-head"><span class="lc-p-n">Problem ${idx + 1}</span><span class="lc-level l${p.level}">${LEVELS[p.level]}</span></div>
                    <h2>${esc(p.title)}</h2>
                    <div class="lc-statement">${p.statement}</div>
                    <h3>Input</h3><div>${p.input}</div>
                    <h3>Output</h3><div>${p.output}</div>
                    ${p.constraints ? `<h3>Constraints</h3><div>${p.constraints}</div>` : ''}
                    ${p.examples.map((ex, k) => `
                        <div class="lc-example">
                            <div><div class="lc-ex-label">Example ${k + 1} — input <button class="lc-copy" data-k="${k}" title="Use as custom input">↪ use</button></div><pre>${esc(ex.in)}</pre></div>
                            <div><div class="lc-ex-label">Expected output</div><pre>${esc(ex.out)}</pre></div>
                            ${ex.why ? `<div class="lc-why">${ex.why}</div>` : ''}
                        </div>`).join('')}
                </div>
                <div class="lc-card">
                    <div class="lc-editor-head"><strong>Your code</strong><span class="lc-small">Python 3 · read from input(), write with print() · no prompts in input()</span></div>
                    <textarea class="lc-code lc-main" rows="14" placeholder="# Write your solution here"></textarea>
                    <details class="lc-custom"><summary>Custom input for ▶ Run</summary><textarea class="lc-stdin" rows="4"></textarea></details>
                    <div class="lc-row">
                        <button class="lc-btn" id="lc-run">▶ Run</button>
                        <button class="lc-btn go" id="lc-submit">✓ Submit (${p.examples.length + p.tests.length} tests)</button>
                        <button class="lc-btn ghost" id="lc-hint">💡 Hint</button>
                        <button class="lc-btn ghost" id="lc-sol">🔑 Solution</button>
                        <button class="lc-btn ghost" id="lc-reset">↺ Clear</button>
                    </div>
                    <div class="lc-hint" hidden>${p.hint}</div>
                    <div class="lc-solution" hidden>${p.explanation ? `<div>${p.explanation}</div>` : ''}<pre>${esc(p.solution)}</pre></div>
                    <pre class="lc-out" hidden></pre>
                    <div class="lc-results"></div>
                    <div class="lc-row lc-nav">
                        ${idx > 0 ? `<a class="lc-btn ghost small" href="#p=${C.problems[idx - 1].slug}">← Previous</a>` : '<span></span>'}
                        ${idx < C.problems.length - 1 ? `<a class="lc-btn ghost small" href="#p=${C.problems[idx + 1].slug}">Next →</a>` : ''}
                    </div>
                </div>`;
            const ta = $('.lc-main', view), stdinTa = $('.lc-stdin', view);
            ta.value = store.get(key, '');
            stdinTa.value = p.examples[0].in;
            editor(ta, () => store.set(key, ta.value));
            $$('.lc-copy', view).forEach(b => b.addEventListener('click', () => {
                stdinTa.value = p.examples[Number(b.dataset.k)].in; $('.lc-custom', view).open = true;
            }));
            const out = $('.lc-out', view), results = $('.lc-results', view);
            const runBtn = $('#lc-run'), subBtn = $('#lc-submit');
            const busy = on => { runBtn.disabled = subBtn.disabled = on; };

            runBtn.addEventListener('click', async () => {
                results.innerHTML = ''; out.hidden = false; out.className = 'lc-out'; out.textContent = '🐍 Running…';
                busy(true);
                try {
                    const inp = stdinTa.value.endsWith('\n') ? stdinTa.value : stdinTa.value + '\n';
                    const r = await Judge.run(ta.value, inp);
                    out.textContent = r.tle ? '⏱ Stopped after 4 seconds — is there an endless loop?' : (r.out + (r.err ? (r.out ? '\n' : '') + r.err : '')) || '(no output)';
                    if (r.err || r.tle) out.classList.add('bad');
                } catch (e) { out.textContent = '⚠️ Python could not load. Check your internet connection and try again.'; out.classList.add('bad'); }
                busy(false);
            });

            subBtn.addEventListener('click', async () => {
                if (!ta.value.trim()) { out.hidden = false; out.className = 'lc-out bad'; out.textContent = 'Write some code first.'; return; }
                out.hidden = true; busy(true);
                const cases = p.examples.map((e, i) => ({ in: e.in.endsWith('\n') ? e.in : e.in + '\n', out: e.out, name: `Example ${i + 1}` }))
                    .concat(p.tests.map((t, i) => ({ in: t.in, out: t.out, name: `Test ${i + 1}` })));
                results.innerHTML = `<div class="lc-verdict">Testing… 0 / ${cases.length}</div><div class="lc-dots"></div>`;
                const dots = $('.lc-dots', results);
                let passed = 0, firstFail = null;
                for (let i = 0; i < cases.length; i++) {
                    const c = cases[i];
                    let r;
                    try { r = await Judge.run(ta.value, c.in); } catch (e) { r = { err: 'Python could not load.', out: '' }; }
                    const ok = !r.err && !r.tle && norm(r.out) === norm(c.out);
                    const status = r.tle ? 'tle' : r.err ? 'err' : ok ? 'ok' : 'wa';
                    if (ok) passed++; else if (!firstFail) firstFail = { c, r, status };
                    dots.insertAdjacentHTML('beforeend', `<span class="lc-dot ${status}" title="${c.name}: ${{ ok: 'passed', wa: 'wrong answer', err: 'error', tle: 'too slow' }[status]}"></span>`);
                    $('.lc-verdict', results).textContent = `Testing… ${i + 1} / ${cases.length}`;
                }
                const all = passed === cases.length;
                $('.lc-verdict', results).innerHTML = all ? `🎉 <strong>Accepted!</strong> All ${cases.length} tests passed.`
                    : `<strong>${passed} / ${cases.length} tests passed.</strong>`;
                $('.lc-verdict', results).className = 'lc-verdict ' + (all ? 'good' : 'bad');
                if (firstFail) {
                    const { c, r, status } = firstFail;
                    const what = { wa: 'Wrong answer', err: 'Your program crashed', tle: 'Too slow (over 4 seconds)' }[status];
                    results.insertAdjacentHTML('beforeend', `<div class="lc-fail"><div><strong>${c.name}: ${what}</strong></div>
                        <div class="lc-fail-grid">
                            <div><div class="lc-ex-label">Input</div><pre>${esc(c.in.length > 1500 ? c.in.slice(0, 1500) + '\n…' : c.in)}</pre></div>
                            <div><div class="lc-ex-label">Expected</div><pre>${esc(c.out.length > 1500 ? c.out.slice(0, 1500) + '\n…' : c.out)}</pre></div>
                            <div><div class="lc-ex-label">Your output</div><pre>${esc((r.out || '').slice(0, 1500))}${r.err ? `\n<span class="bad">${esc(r.err)}</span>` : ''}</pre></div>
                        </div></div>`);
                }
                if (all) { markSolved(cid, p.slug); paintList(); $$('.lc-item', list).forEach(a => a.classList.toggle('active', a.dataset.slug === p.slug)); }
                busy(false);
            });

            $('#lc-hint').addEventListener('click', () => { const h = $('.lc-hint', view); h.hidden = !h.hidden; });
            $('#lc-sol').addEventListener('click', () => {
                const s = $('.lc-solution', view);
                if (s.hidden && !confirm('Show the solution? Try the hint first — you learn the most by solving it yourself.')) return;
                s.hidden = !s.hidden;
            });
            $('#lc-reset').addEventListener('click', () => {
                if (ta.value.trim() && !confirm('Clear your code for this problem?')) return;
                ta.value = ''; store.set(key, ''); out.hidden = true; results.innerHTML = '';
            });
            if (window.innerWidth < 900) view.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
        return { open, get current() { return current; } };
    }

    window.addEventListener('DOMContentLoaded', () => {
        const page = document.body.dataset.page;
        if (page === 'hub') hub();
        if (page === 'class') classPage();
    });
})();
